# single-flight + lock sketch (Go, match-worker)
func lookup(ctx context.Context, acct, cusip, day string) (payload []byte, err error) {
    key := fmt.Sprintf("mk:%s:%s", day, acct)
    if v, err := rdb.HGet(ctx, key, cusip).Bytes(); err == nil {
        if string(v) == "-" { return nil, errMissSentinel }
        return v, nil
    }
    lock := fmt.Sprintf("mklock:%s:%s:%s", day, acct, cusip)
    ok, _ := rdb.SetNX(ctx, lock, hostname, 2*time.Second).Result()
    if !ok {
        time.Sleep(20 * time.Millisecond)
        if v, err := rdb.HGet(ctx, key, cusip).Bytes(); err == nil {
            return v, nil
        }
        return lookupPG(ctx, acct, cusip, day) // degrade, do not loop forever
    }
    defer rdb.Del(ctx, lock)
    payload, err = lookupPG(ctx, acct, cusip, day)
    if err == errNotFound {
        rdb.Set(ctx, fmt.Sprintf("nx:%s:%s:%s", day, acct, cusip), "-", 90*time.Second)
        return nil, err
    }
    rdb.HSet(ctx, key, cusip, payload)
    rdb.Expire(ctx, key, 36*time.Hour)
    return payload, err
}
